struct OrderGateway { virtual void insert(const Order&) = 0; virtual ~OrderGateway() = default; };
class OrderService {                        // the application boundary
 public:
  OrderService(OrderGateway& gw, TxManager& tx) : gw_(gw), tx_(tx) {}
  void place(const OrderRequest& r) {
    Tx tx = tx_.begin();                    // RAII guard: commit() or rollback on scope exit
    gw_.insert(Order::from(r));
    tx.commit();
  }
 private:
  OrderGateway& gw_; TxManager& tx_;
};
